import Foundation
import AVFoundation
import UIKit

public final class AudioEffectManager {
    public static let shared = AudioEffectManager()

    private static let pageTurnWavBase64 = ""
    private var pageTurnPlayer: AVAudioPlayer?
    private let soundEffectsKey = "sound_effects_enabled"

    public var isSoundEnabled: Bool {
        get {
            if UserDefaults.standard.object(forKey: soundEffectsKey) == nil {
                return true
            }
            return UserDefaults.standard.bool(forKey: soundEffectsKey)
        }
        set {
            UserDefaults.standard.set(newValue, forKey: soundEffectsKey)
        }
    }

    private init() {
        prepareAudio()
    }

    private func prepareAudio() {
        guard let data = Data(base64Encoded: Self.pageTurnWavBase64) else { return }
        do {
            try AVAudioSession.sharedInstance().setCategory(.ambient, options: .mixWithOthers)
            try AVAudioSession.sharedInstance().setActive(true)
            pageTurnPlayer = try AVAudioPlayer(data: data)
            pageTurnPlayer?.prepareToPlay()
            pageTurnPlayer?.volume = 1.0
        } catch {
            print("Failed to initialize AudioEffectManager: \(error)")
        }
    }

    public func playPageTurn() {
        guard isSoundEnabled else { return }
        DispatchQueue.main.async {
            let haptic = UIImpactFeedbackGenerator(style: .light)
            haptic.prepare()
            haptic.impactOccurred()

            if let player = self.pageTurnPlayer {
                if player.isPlaying {
                    player.stop()
                    player.currentTime = 0
                }
                player.play()
            } else {
                self.prepareAudio()
                self.pageTurnPlayer?.play()
            }
        }
    }

    public func playToggle(enabled: Bool) {
        DispatchQueue.main.async {
            let haptic = UINotificationFeedbackGenerator()
            haptic.notificationOccurred(enabled ? .success : .warning)
            if enabled {
                self.playPageTurn()
            }
        }
    }
}
